function openServiceSelectionModal(){serviceSelectionModalElement.classList.add("show");bodyElement.classList.add("overflow-hidden")}function closeServiceSelectionModal(){serviceSelectionModalElement.classList.remove("show");bodyElement.classList.remove("overflow-hidden")}const bodyElement=document.body,serviceSelectionButtonElement=document.getElementById("service-selection--button"),serviceSelectionModalElement=document.getElementById("service-selection__modal"),closeModalButton=document.querySelector(".close-modal__button"),tbaoButtonElements=document.querySelectorAll(".tbao-button");serviceSelectionButtonElement.addEventListener("click",function(){openServiceSelectionModal()});closeModalButton.addEventListener("click",closeServiceSelectionModal);tbaoButtonElements.forEach(n=>n.addEventListener("click",closeServiceSelectionModal));